// components/QuickCatalog.jsx
"use client";
import { useState } from "react";
import { products } from "@/data/products";

export default function QuickCatalog() {
  const [cart, setCart] = useState([]);

  // Fungsi Tambah ke Keranjang
  const addToCart = (product) => {
    setCart((prevCart) => {
      const existing = prevCart.find((item) => item.id === product.id);
      if (existing) {
        return prevCart.map((item) =>
          item.id === product.id ? { ...item, qty: item.qty + 1 } : item
        );
      }
      return [...prevCart, { ...product, qty: 1 }];
    });
  };

  // Hitung Total Harga Otomatis pakai .reduce()
  const totalPrice = cart.reduce((total, item) => total + item.price * item.qty, 0);

  // Fungsi Kirim ke WhatsApp
  const sendToWhatsApp = () => {
    if (cart.length === 0) {
      alert("Keranjang masih kosong, pilih layanan dulu ya!");
      return;
    }

    const phoneNumber = "6281234567890"; // Ganti pakai nomor WhatsApp lu
    let message = "Halo Genesis Studio, saya mau pesan:\n";
    
    cart.forEach((item) => {
      message += `- ${item.name} (${item.qty}x) - Rp ${item.price * item.qty}\n`;
    });
    
    message += `\nTotal Keseluruhan: Rp ${totalPrice.toLocaleString("id-ID")}`;

    const url = `https://wa.me/${phoneNumber}?text=${encodeURIComponent(message)}`;
    window.open(url, "_blank");
  };

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-8">
      <div className="text-center mb-10">
        <h1 className="text-3xl font-extrabold text-slate-900">Genesis Quick Catalog</h1>
        <p className="text-slate-600 mt-2">Pilih layanan digital, masukkan keranjang, dan langsung order via WhatsApp.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Sisi Kiri: Daftar Produk (.map) */}
        <div className="space-y-4">
          <h2 className="text-xl font-bold text-slate-800">Daftar Layanan</h2>
          {products.map((product) => (
            <div key={product.id} className="bg-white border border-slate-200 p-4 rounded-xl shadow-sm flex justify-between items-center">
              <div>
                <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded-md font-semibold">{product.category}</span>
                <h3 className="font-bold text-lg mt-1">{product.name}</h3>
                <p className="text-slate-500 text-sm">{product.desc}</p>
                <p className="text-blue-600 font-semibold mt-2">Rp {product.price.toLocaleString("id-ID")}</p>
              </div>
              <button
                onClick={() => addToCart(product)}
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition shrink-0 ml-4"
              >
                + Pilih
              </button>
            </div>
          ))}
        </div>

        {/* Sisi Kanan: Ringkasan Keranjang */}
        <div className="bg-white border border-slate-200 p-6 rounded-2xl shadow-sm h-fit sticky top-6">
          <h2 className="text-xl font-bold text-slate-800 mb-4">Keranjang Pesanan</h2>
          
          {cart.length === 0 ? (
            <p className="text-slate-400 text-sm py-8 text-center border-2 border-dashed rounded-xl">Belum ada item dipilih.</p>
          ) : (
            <div className="space-y-4">
              <div className="divide-y max-h-60 overflow-y-auto">
                {cart.map((item) => (
                  <div key={item.id} className="py-2 flex justify-between text-sm">
                    <span>{item.name} <strong className="text-blue-600">({item.qty}x)</strong></span>
                    <span>Rp {(item.price * item.qty).toLocaleString("id-ID")}</span>
                  </div>
                ))}
              </div>

              <div className="border-t pt-4 flex justify-between font-bold text-lg">
                <span>Total:</span>
                <span className="text-blue-600">Rp {totalPrice.toLocaleString("id-ID")}</span>
              </div>

              <button
                onClick={sendToWhatsApp}
                className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 rounded-xl transition text-center shadow-md"
              >
                📲 Checkout ke WhatsApp
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}